<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Modern Kanban Board</title>
    <style>
        :root {
            --bg-color: #f4f7f9;
            --column-bg: #ebedf0;
            --card-bg: #ffffff;
            --text-main: #333;
            --primary-blue: #007bff;
            --danger-red: #dc3545;
            --shadow: 0 2px 5px rgba(0,0,0,0.1);
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-main);
            margin: 0;
            padding: 20px;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        h1 { margin-bottom: 30px; }

        /* Input Area */
        .input-section {
            margin-bottom: 40px;
            display: flex;
            gap: 10px;
            width: 100%;
            max-width: 500px;
        }

        #new-card {
            flex: 1;
            padding: 12px;
            border: 1px solid #ccc;
            border-radius: 6px;
            font-size: 1rem;
            outline: none;
        }

        #add-card {
            padding: 10px 20px;
            background-color: var(--primary-blue);
            color: white;
            border: none;
            border-radius: 6px;
            cursor: pointer;
            font-weight: bold;
        }

        #add-card:hover { background-color: #0056b3; }

        /* Board Layout */
        .board {
            display: flex;
            gap: 20px;
            width: 100%;
            max-width: 1200px;
            align-items: flex-start;
            justify-content: center;
            flex-wrap: wrap;
        }

        .column {
            background-color: var(--column-bg);
            border-radius: 8px;
            width: 350px;
            min-height: 400px;
            display: flex;
            flex-direction: column;
            padding: 15px;
            box-shadow: var(--shadow);
        }

        .column h2 {
            margin-top: 0;
            font-size: 1.2rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .count {
            background: #ddd;
            padding: 2px 8px;
            border-radius: 12px;
            font-size: 0.9rem;
        }

        .card-container {
            flex-grow: 1;
            min-height: 100px;
        }

        /* Card Styling */
        .card {
            background-color: var(--card-bg);
            border-radius: 6px;
            padding: 15px;
            margin-bottom: 12px;
            box-shadow: var(--shadow);
            cursor: grab;
            position: relative;
            word-wrap: break-word;
        }

        .card:active { cursor: grabbing; }

        .card-del {
            position: absolute;
            top: 5px;
            right: 5px;
            background: none;
            border: none;
            color: #ccc;
            cursor: pointer;
            font-size: 14px;
            padding: 5px;
        }

        .card-del:hover { color: var(--danger-red); }

        /* Drag and Drop Visuals */
        .column.drag-over {
            background-color: #dfe3e6;
            border: 2px dashed #bbb;
        }
    </style>
</head>
<body>

    <h1>Kanban Board</h1>

    <div class="input-section">
        <input type="text" id="new-card" placeholder="Enter a new task..." />
        <button id="add-card">Add Card</button>
    </div>

    <div class="board">
        <!-- To Do -->
        <div id="col-todo" class="column" ondrop="drop(event)" ondragover="allowDrop(event)" ondragleave="clearDragOver(event)">
            <h2>To Do <span class="count" id="count-todo">0</span></h2>
            <div class="card-container" id="container-todo"></div>
        </div>

        <!-- Doing -->
        <div id="col-doing" class="column" ondrop="drop(event)" ondragover="allowDrop(event)" ondragleave="clearDragOver(event)">
            <h2>Doing <span class="count" id="count-doing">0</span></h2>
            <div class="card-container" id="container-doing"></div>
        </div>

        <!-- Done -->
        <div id="col-done" class="column" ondrop="drop(event)" ondragover="allowDrop(event)" ondragleave="clearDragOver(event)">
            <h2>Done <span class="count" id="count-done">0</span></h2>
            <div class="card-container" id="container-done"></div>
        </div>
    </div>

    <script>
        // State Management
        let boardState = JSON.parse(localStorage.getItem('kanbanData')) || [];

        const input = document.getElementById('new-card');
        const addBtn = document.getElementById('add-card');

        // Initialize Board
        function init() {
            renderBoard();
        }

        // Save to LocalStorage
        function saveState() {
            localStorage.setItem('kanbanData', JSON.stringify(boardState));
        }

        // Render the UI based on state
        function renderBoard() {
            const containers = {
                'todo': document.getElementById('container-todo'),
                'doing': document.getElementById('container-doing'),
                'done': document.getElementById('container-done')
            };

            const counts = {
                'todo': 0,
                'doing': 0,
                'done': 0
            };

            // Clear all containers
            Object.values(containers).forEach(c => c.innerHTML = '');

            // Populate cards
            boardState.forEach(card => {
                const cardEl = document.createElement('div');
                cardEl.className = 'card';
                cardEl.draggable = true;
                cardEl.id = `card-${card.id}`;
                cardEl.innerHTML = `
                    ${card.text}
                    <button class="card-del" onclick="deleteCard('${card.id}')">✕</button>
                `;

                // Drag Handlers for Card
                cardEl.ondragstart = (e) => {
                    e.dataTransfer.setData('cardId', card.id);
                    e.dataTransfer.setData('sourceCol', card.status);
                };

                containers[card.status].appendChild(cardEl);
                counts[card.status]++;
            });

            // Update Counts
            Object.keys(counts).forEach(key => {
                document.getElementById(`count-${key}`).innerText = counts[key];
            });

            saveState();
        }

        // Add Card logic
        addBtn.addEventListener('click', () => {
            const text = input.value.trim();
            if (text) {
                const newCard = {
                    id: Date.now().toString(),
                    text: text,
                    status: 'todo'
                };
                boardState.push(newCard);
                input.value = '';
                renderBoard();
            }
        });

        // Delete Card logic
        window.deleteCard = function(id) {
            boardState = boardState.filter(c => c.id !== id);
            renderBoard();
        };

        // Drag and Drop Logic
        window.allowDrop = function(e) {
            e.preventDefault();
            e.currentTarget.classList.add('drag-over');
        };

        window.clearDragOver = function(e) {
            e.currentTarget.classList.remove('drag-over');
        };

        window.drop = function(e) {
            e.preventDefault();
            const columnEl = e.currentTarget;
            columnEl.classList.remove('drag-over');

            const cardId = e.dataTransfer.getData('cardId');
            const targetStatus = columnEl.id.replace('col-', '');

            // Update state
            boardState = boardState.map(card => {
                if (card.id === cardId) {
                    return { ...card, status: targetStatus };
                }
                return card;
            });

            renderBoard();
        };

        // Allow pressing Enter to add cards
        input.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') addBtn.click();
        });

        // Initial Run
        init();
    </script>
</body>
</html>
